export function runCasl(programs:string[],date:[number,number,number],options:{blanks?:number[];extension?:[number,number];epoch?:number}={}){const banks=[['LAD GR4,ACCMDAYS','LAD GR4,ACCMDAYS,GR3','LAD GR4,ACCMDAYS,GR5','LD GR4,ACCMDAYS','LD GR4,ACCMDAYS,GR3','LD GR4,ACCMDAYS,GR5'],['JMI BREAK','JNZ BREAK','JOV BREAK','JPL BREAK','JUMP BREAK','JZE BREAK'],['JMI FIN','JNZ FIN','JOV FIN','JUMP FIN','JZE FIN'],['AND GR0,=#FFFE','AND GR0,=1','OR GR0,=#FFFE','OR GR0,=1','XOR GR0,=#FFFF','XOR GR0,=1']],blanks=options.blanks??[1,5,1,5],ops:string[]=[],labels=new Map<string,number>(),mem=new Map<number,number>(),base=20000;let at=base;for(let pi=0;pi<programs.length;pi++){for(let row of programs[pi].split('\n')){const nr=Number(row.trim().match(/^\d+/)?.[0]);row=row.replace(/^\s*\d+\s+/,'').split(';')[0].trim();if(!row||row==='END')continue;for(let b=0;b<4;b++)row=row.replace('［'+'abcd'[b]+'］',banks[b][blanks[b]]);let parts=row.split(/\s+/),op=parts[0];const known=['RPUSH','RPOP','LD','LAD','SUBL','SUBA','ADDL','ADDA','CPA','AND','OR','XOR','JMI','JNZ','JZE','JOV','JPL','JUMP','CALL','RET'];if(!known.includes(op)){const label=parts.shift()!;op=parts.shift()!;if(op==='DC'){labels.set(label,at);for(const n of parts.join('').split(','))mem.set(at++,Number(n));continue;}labels.set(label,ops.length);if(op==='START')continue;row=[op,...parts].join(' ');}if(op==='END')continue;ops.push(row);if(pi===0&&options.extension&&nr===options.extension[0])ops.push(['JMI','JNZ','JOV','JPL','JZE'][options.extension[1]]+' EXIT');}}
 const r=[0,101,30000,303,404,505,606,707],saved=r.slice(1),stack:number[][]=[],ret:number[]=[],initial=r.slice();date.forEach((v,i)=>mem.set(30000+i,v));let pc=labels.get('DAYOFFST')!,steps=0,of=0,z=0,s=0;const word=(n:number)=>n&65535,signed=(n:number)=>n&32768?n-65536:n,reg=(s:string)=>Number(s.slice(2)),constant=(v:string)=>v.startsWith('#')?parseInt(v.slice(1),16):Number(v),flags=(n:number,o=0)=>{const w=word(n);of=o;z=w===0?1:0;s=w&32768?1:0;return w;};
 function address(parts:string[]){const v=parts[0],n=labels.get(v)??constant(v);if(!Number.isFinite(n))throw Error('BAD_ADDRESS');return word(n+(parts[1]?r[reg(parts[1])]:0));}
 function value(parts:string[]){if(parts.length===1&&/^GR\d$/.test(parts[0]))return r[reg(parts[0])];if(parts[0].startsWith('='))return constant(parts[0].slice(1));const a=address(parts);if(!mem.has(a))throw Error('UNINITIALIZED_READ');return mem.get(a)!;}
 while(pc<ops.length){if(++steps>4000000)throw Error('CASL_STEP_LIMIT');const line=ops[pc++],sp=line.indexOf(' '),op=sp<0?line:line.slice(0,sp),arg=sp<0?[]:line.slice(sp+1).replaceAll(' ','').split(',');if(op==='RPUSH'){stack.push(r.slice(1));continue;}if(op==='RPOP'){const v=stack.pop();if(!v)throw Error('STACK_UNDERFLOW');r.splice(1,7,...v);continue;}if(op==='RET'){if(!ret.length)break;pc=ret.pop()!;continue;}if(op==='CALL'){if(arg[0]==='DIVISIBL'){r[0]=r[2]%r[3]===0?1:0;of=1;z=0;s=1;}else{ret.push(pc);pc=labels.get(arg[0])!;}continue;}if(op.startsWith('J')){const take=op==='JUMP'||op==='JMI'&&s===1||op==='JNZ'&&z===0||op==='JZE'&&z===1||op==='JOV'&&of===1||op==='JPL'&&s===0&&z===0;if(take){const target=labels.get(arg[0]);if(target===undefined)throw Error('BAD_BRANCH');pc=target;}continue;}const dst=reg(arg[0]);if(op==='LAD'){r[dst]=address(arg.slice(1));continue;}const a=r[dst],b=value(arg.slice(1));if(op==='LD')r[dst]=flags(b);else if(op==='CPA'){of=0;z=a===b?1:0;s=signed(a)<signed(b)?1:0;}else if(op==='ADDL')r[dst]=flags(a+b,a+b>65535?1:0);else if(op==='SUBL')r[dst]=flags(a-b,a<b?1:0);else if(op==='ADDA'||op==='SUBA'){const n=op==='ADDA'?signed(a)+signed(b):signed(a)-signed(b);r[dst]=flags(n,n>32767||n< -32768?1:0);}else if(op==='AND')r[dst]=flags(a&b);else if(op==='OR')r[dst]=flags(a|b);else if(op==='XOR')r[dst]=flags(a^b);else throw Error('UNSUPPORTED_CASL:'+op);}
 return{gr0:r[0],of,registersRestored:r.slice(1).every((v,i)=>v===saved[i]),steps,initial,registers:r};}
